/* ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   COMBINE & SEED
   ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */
const allDestinations = [
  ...india,
  ...asia,
  ...europe,
  ...middleEast,
  ...africa,
  ...americas,
  ...oceania,
];

async function seed350() {
  console.log(`\n=== Seeding ${allDestinations.length} destinations ===\n`);
  console.log(`India: ${india.length} | Asia: ${asia.length} | Europe: ${europe.length}`);
  console.log(`Middle East: ${middleEast.length} | Africa: ${africa.length} | Americas: ${americas.length} | Oceania: ${oceania.length}\n`);

  for (let i = 0; i < allDestinations.length; i += BATCH_SIZE) {
    const batch = allDestinations.slice(i, i + BATCH_SIZE);
    await db.insert(destinations).values(batch).onConflictDoNothing();
    console.log(`Batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(allDestinations.length / BATCH_SIZE)} done (${Math.min(i + BATCH_SIZE, allDestinations.length)}/${allDestinations.length})`);
  }

  // Also update existing 8 destinations that may have null extended columns
  console.log('\nUpdating existing destinations with missing extended columns...');
  const { sql: rawSql } = await import('drizzle-orm');
  await db.execute(rawSql`
    UPDATE destinations SET
      visa_status = COALESCE(visa_status, visa_json->>'type'),
      safety_score = COALESCE(safety_score, (score_json->>'safety')::int, 75),
      weather_score = COALESCE(weather_score, (score_json->>'weatherScore')::int, 70),
      infrastructure_score = COALESCE(infrastructure_score, (score_json->>'touristInfrastructure')::int, 70),
      value_score = COALESCE(value_score, (score_json->>'affordability')::int, 70),
      budget_per_day = COALESCE(budget_per_day, (budget_json->'budget'->>'amount')::int),
      budget_mid_per_day = COALESCE(budget_mid_per_day, (budget_json->'comfort'->>'amount')::int),
      budget_luxury_per_day = COALESCE(budget_luxury_per_day, (budget_json->'luxury'->>'amount')::int),
      trending_score = COALESCE(trending_score, 50),
      flag_emoji = COALESCE(flag_emoji, CASE WHEN country_code = 'IN' THEN '🇮🇳' ELSE '' END)
    WHERE visa_status IS NULL OR safety_score IS NULL OR budget_per_day IS NULL
  `);

  console.log('\n=== Done! ===\n');
  process.exit(0);
}

seed350().catch((err) => {
  console.error('Fatal:', err);
  process.exit(1);
});
